// Parser for docs/API_REFERENCE.md (generated by `npm run docs:api -w server` from the live router).
//
// The file is a set of tables
//
//   | Method | Path | Access | Validated |
//   | POST | `/auth/login` | Public | Yes |
//
// under "## <Section>" headings, plus an "Access levels" table that states how many endpoints each level has and a
// sentence "Base path: `/api` ... 235 endpoints.". The parser returns every endpoint with its access level normalised to
//
//   public | optional | member | chapter-admin | admin | super-admin
//
// and the numbers the document states about itself, so a test can prove the parse is complete.
//
// Zero dependencies, Node 20+.

import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

/** Access levels in increasing order of privilege. `public` and `optional` need no token. */
export const ACCESS_LEVELS = ['public', 'optional', 'member', 'chapter-admin', 'admin', 'super-admin'];

/** The words the document uses, lower-cased, mapped to the normalised level. */
const ACCESS_WORDS = new Map([
  ['public', 'public'],
  ['public (personalised when signed in)', 'optional'],
  ['public (personalized when signed in)', 'optional'],
  ['signed in', 'member'],
  ['chapter admin+', 'chapter-admin'],
  ['admin+', 'admin'],
  ['super admin', 'super-admin'],
]);

const METHODS = new Set(['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'HEAD', 'OPTIONS']);

/** Normalise the text of an "Access" cell. Throws on a word this parser does not know (the document changed shape). */
export function normaliseAccess(text) {
  const key = String(text ?? '').replace(/\s+/g, ' ').trim().toLowerCase();
  const level = ACCESS_WORDS.get(key);
  if (!level) throw new Error(`Unknown access level in API reference: "${text}"`);
  return level;
}

/** Cells of a markdown table row: "| a | `b` | c |" -> ["a", "`b`", "c"]. Returns null when the line is not a table row. */
function cells(line) {
  const trimmed = line.trim();
  if (!trimmed.startsWith('|') || !trimmed.endsWith('|')) return null;
  return trimmed.slice(1, -1).split('|').map((cell) => cell.trim());
}

/**
 * Parse the markdown text of the API reference.
 * @returns {{
 *   basePath: string,
 *   statedTotal: number | null,
 *   statedLevels: Record<string, number>,
 *   endpoints: Array<{ method: string, path: string, access: string, validated: boolean, section: string }>
 * }}
 */
export function parseApiReference(markdown) {
  const lines = String(markdown).split(/\r?\n/);

  const baseMatch = /Base path:\s*`([^`]+)`/.exec(markdown);
  const totalMatch = /(\d+)\s+endpoints\b/.exec(markdown);
  const basePath = baseMatch ? baseMatch[1].replace(/\/+$/, '') : '/api';
  const statedTotal = totalMatch ? Number(totalMatch[1]) : null;

  const statedLevels = {};
  const endpoints = [];
  let section = '';

  for (const line of lines) {
    const heading = /^##\s+(.+?)\s*$/.exec(line);
    if (heading) {
      section = heading[1];
      continue;
    }
    const row = cells(line);
    if (!row) continue;

    // "Access levels" table: | Public | No token needed | 12 |
    if (row.length === 3 && /^\d+$/.test(row[2]) && ACCESS_WORDS.has(row[0].toLowerCase())) {
      statedLevels[normaliseAccess(row[0])] = Number(row[2]);
      continue;
    }

    // Endpoint table: | POST | `/auth/login` | Public | Yes |
    if (row.length >= 3 && METHODS.has(row[0])) {
      const pathMatch = /^`([^`]+)`$/.exec(row[1]);
      if (!pathMatch) throw new Error(`API reference row without a backticked path: ${line}`);
      endpoints.push({
        method: row[0],
        path: pathMatch[1],
        access: normaliseAccess(row[2]),
        validated: /^yes$/i.test(row[3] ?? ''),
        section,
      });
    }
  }

  return { basePath, statedTotal, statedLevels, endpoints };
}

/** Default location of the reference: <repo>/docs/API_REFERENCE.md */
export const DEFAULT_API_REFERENCE = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..', '..', '..', 'docs', 'API_REFERENCE.md'
);

/** Read and parse the reference from disk. */
export async function loadApiReference(file = DEFAULT_API_REFERENCE) {
  return parseApiReference(await readFile(file, 'utf8'));
}

/** Number of endpoints per normalised level (every level present, zero when absent). */
export function countByLevel(endpoints) {
  const counts = Object.fromEntries(ACCESS_LEVELS.map((level) => [level, 0]));
  for (const endpoint of endpoints) counts[endpoint.access] += 1;
  return counts;
}
